PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?m3) WHERE {
  { SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?wp a :WellProduction ; :concession ?c ; :oil ?oil .
    } GROUP BY ?c }
  ?s a :Stake ; :concession ?c ; :partner ?co ; :percent ?pct .
  ?co :name ?n .
  FILTER(REGEX(?n, "^YPF", "i"))
}
